int main() {
    int car_year_2007 = 20000;
    float depreciation = 0.21;
    int years = 3;
    float car_price;
    car_price = car_year_2007;

    for (int i = 0; i < years; i++) {
        car_price = (1 - depreciation) * car_price;
    }

    printf("%f\n", car_price);
    return 0;
